def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bidirectional Dijkstra's algorithm

    def dijkstra(start, target):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        visited = set()

        while heap:
            d, u = heapq.heappop(heap)
            if u in visited:
                continue
            visited.add(u)
            if u == target:
                return d
            for v, w in adj[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return float('inf')

    # Run Dijkstra from both ends
    dist_from_s = dijkstra(s, t)
    dist_from_t = dijkstra(t, s)

    if dist_from_s == float('inf'):
        return -1

    return dist_from_s
