import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bidirectional Dijkstra's algorithm
    def dijkstra(start, end):
        dist = [float('inf')] * n
        dist[start] = 0
        heap = [(0, start)]
        while heap:
            current_dist, u = heapq.heappop(heap)
            if u == end:
                return current_dist
            if current_dist > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(heap, (dist[v], v))
        return float('inf')

    # Run Dijkstra from both ends
    dist_s = dijkstra(s, t)
    dist_t = dijkstra(t, s)

    # Check if either direction found a path
    if dist_s != float('inf') or dist_t != float('inf'):
        return min(dist_s, dist_t)
    return -1
