```python
import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Initialize distances
    dist = [float('inf')] * n
    dist[s] = 0

    # Bucket-queue (priority queue using heapq)
    # Each bucket is a list of nodes with the same distance
    # We use a dictionary to map distance values to lists of nodes
    buckets = {}

    # Initialize buckets
    for node in range(n):
        if node == s:
            dist[node] = 0
        if dist[node] not in buckets:
            buckets[dist[node]] = []
        buckets[dist[node]].append(node)

    # Check if the starting node is already in the correct bucket
    if dist[s] in buckets:
        buckets[dist[s]].remove(s)

    # Bucket-queue algorithm
    while buckets:
        # Get the smallest distance bucket
        min_dist = min(buckets.keys())
        bucket = buckets[min_dist]

        # Process each node in the bucket
        for node in bucket:
            for neighbor, weight in adj[node]:
                if dist[neighbor] > dist[node] + weight:
                    # Update distance
                    dist[neighbor] = dist[node] + weight
                    # Remove from old bucket if exists
                    if dist[neighbor] in buckets:
                        if neighbor in buckets[dist[neighbor]]:
                            buckets[dist[neighbor]].remove(neighbor)
                    # Add to new bucket
                    if dist[neighbor] not in buckets:
                        buckets[dist[neighbor]] = []
                    buckets[dist[neighbor]].append(neighbor)

        # Remove the processed bucket
        del buckets[min_dist]

    return dist[t] if dist[t] != float('inf') else -1
