def solve(n, edges):
    from collections import deque

    def label_propagation():
        labels = list(range(n))
        label_to_nodes = {i: [i] for i in range(n)}
        node_to_label = {i: i for i in range(n)}

        def find_label(label):
            if label_to_nodes[label] == [label]:
                return label
            else:
                return find_label(node_to_label[label])

        def union(u, v):
            label_u = find_label(node_to_label[u])
            label_v = find_label(node_to_label[v])
            if label_u != label_v:
                label_to_nodes[label_u].extend(label_to_nodes[label_v])
                for node in label_to_nodes[label_v]:
                    node_to_label[node] = label_u
                label_to_nodes.pop(label_v)
                node_to_label.pop(label_v)

        for u, v in edges:
            union(u, v)

        unique_labels = set()
        for i in range(n):
            unique_labels.add(find_label(node_to_label[i]))
        return len(unique_labels)

    return label_propagation()
