from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # BFS with shortest path using deque for BFS
    distance = [-1] * n
    distance[s] = 0
    queue = deque([s])

    while queue:
        u = queue.popleft()
        for v, w in graph[u]:
            if distance[v] == -1:
                distance[v] = distance[u] + w
                queue.append(v)
            else:
                # If a shorter path is found, update the distance
                if distance[v] > distance[u] + w:
                    distance[v] = distance[u] + w
                    queue.append(v)

    return distance[t]
