def solve(n, edges):
    # Initialize adjacency list
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Track visited nodes
    visited = [False] * n

    # Count connected components
    component_count = 0

    # Depth-first search to traverse component
    def dfs(node):
        if visited[node]:
            return
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)

    # Iterate through all nodes
    for i in range(n):
        if not visited[i]:
            dfs(i)
            component_count += 1

    return component_count
```

