def solve(nums, k):
    def count_less_equal(x):
        return sum(1 for num in nums if num <= x)

    low = min(nums)
    high = max(nums)

    while low < high:
        mid = (low + high) // 2
        if count_less_equal(mid) < k:
            low = mid + 1
        else:
            high = mid

    return low
