    dist = [float('inf')] * n
    dist[s] = 0
    pq = [(0, s)]

    while pq:
        current_dist, u = pq.pop(0)
        if current_dist > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                pq.append((dist[v], v))

    return dist[t] if dist[t] != float('inf') else -1
